import {
	QueryCommand,
} from '@aws-sdk/client-dynamodb';
import { LambdaClient, InvokeCommand } from '@aws-sdk/client-lambda';
import { validateTenantAccess } from 'admin-auth';

const lambdaClient = new LambdaClient({ region: process.env.AWS_REGION });

// admin* phases are not on the public /amfa route (amfa-442 #1): invoke the
// login-service function directly with IAM. The tenant comes from the
// validated path id, never from the request body.
const fetchAmfaSecrets = async (id) => {
	const res = await lambdaClient.send(new InvokeCommand({
		FunctionName: process.env.AMFA_FUNCTION_ARN,
		Payload: JSON.stringify({
			headers: { Origin: `https://${id}.idapersona.${process.env.AMFA_BASE_URL}` },
			body: JSON.stringify({ phase: 'admingetsecretinfo', tenantid: id }),
		}),
	}));
	if (res.FunctionError) throw new Error(`amfa invoke failed: ${res.FunctionError}`);
	return JSON.parse(Buffer.from(res.Payload ?? []).toString() || '{}');
};

export const getResData = async (event, dynamodb) => {
	const tenantId = event.pathParameters?.id;

	// Validate access using lambda layer
	const authResult = await validateTenantAccess(event, tenantId);
	
	if (!authResult.authorized) {
		const error = new Error(authResult.error || 'Access Denied');
		error.statusCode = authResult.statusCode || 403;
		throw error;
	}

	//fetch tenant Info - use Query with composite key
	const params = {
		TableName: `amfa-tenanttable`,
		KeyConditionExpression: 'id = :id AND begins_with(sk, :sk_prefix)',
		ExpressionAttributeValues: {
			':id': { S: `TENANT#${tenantId}` },
			':sk_prefix': { S: 'TENANT#' }
		}
	};

	const result = await dynamodb.send(new QueryCommand(params));

	console.log('get tenants result', result);

	const item = result.Items && result.Items.length > 0 ? result.Items[0] : null;


	const res = await fetchAmfaSecrets(tenantId);
	const resJson = JSON.parse(res.body || '{}');

	console.log('get secret json from amfa', resJson);

	// Handle error responses from amfa API (e.g. when tenant secrets are not yet provisioned)
	if (!resJson.message || typeof resJson.message === 'string') {
		console.error('amfa API returned error or invalid response:', resJson.message);
		const error = new Error(`Failed to fetch tenant secrets: ${resJson.message || 'No response from amfa service'}`);
		error.statusCode = res.statusCode === 200 ? 502 : res.statusCode;
		throw error;
	}

	const smtp = resJson.message;
	smtp.secure = smtp.secure === "true" || smtp.secure === true ? true : false;

	if (item && item.name) {

		return {
			id: tenantId,
			name: decodeURIComponent(item.name.S),
			contact: item.contact.S,
			url: item.url.S,
			endUserSpUrl: item.endUserSpUrl.S,
			samlproxy: item.samlproxy?.BOOL,
			adminApiUrl: `https://api.${process.env.ROOT_DOMAIN_NAME}`,
			endUserSpRegion: process.env.AWS_REGION,
			endUserSpWebClientId: item.spPortalClientId?.S || '',
			endUserSpUserpoolId: item.userpool?.S || '',
			endUserSpOauthDomain: smtp.oauthdomain,
			org_id: item.org_id?.S || 'default', // Include org_id in response
			...smtp,
			// branding: item.branding,
		};
	}

	throw new Error('Not Found!');
};

export default getResData;
